#include ZETA_SOURCE
#include <chrono>
#include <cstdio>
#include <random>
#ifndef VALUE_BITS
#define VALUE_BITS 32
#endif
#if VALUE_BITS == 32
using T=std::uint32_t;
#else
using T=std::uint64_t;
#endif
using Clock=std::chrono::steady_clock;
[[gnu::noinline]] void run0(std::vector<T>&a){subset_zeta_transform(a);}
[[gnu::noinline]] void run1(std::vector<T>&a){superset_zeta_transform(a);}
[[gnu::noinline]] void run2(std::vector<T>&a){subset_mobius_transform(a);}
[[gnu::noinline]] void run3(std::vector<T>&a){superset_mobius_transform(a);}

int main(int argc,char**argv){
 const unsigned lg=argc>1?std::strtoul(argv[1],nullptr,10):20;const unsigned op=argc>2?std::strtoul(argv[2],nullptr,10):0;
 const std::size_t n=std::size_t{1}<<lg, reps=std::max(std::size_t{4},(std::size_t{1}<<23)/n);
 std::vector<T> a(n);for(std::size_t i=0;i<n;++i)a[i]=static_cast<T>(i*137);
 auto t=Clock::now();
 switch(op){case 0:for(std::size_t rep=0;rep<reps;++rep)run0(a);break;case 1:for(std::size_t rep=0;rep<reps;++rep)run1(a);break;case 2:for(std::size_t rep=0;rep<reps;++rep)run2(a);break;default:for(std::size_t rep=0;rep<reps;++rep)run3(a);}

 const auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-t).count();std::uint64_t sum=0;for(T x:a)sum+=x;
 std::printf("{\"ns\":%lld,\"sum\":%llu,\"n\":%zu,\"reps\":%zu}\n",static_cast<long long>(ns),static_cast<unsigned long long>(sum),n,reps);
}

